cd /tmp && cat > ParseBinlog2.cs << 'EOF'
using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("/tmp/sv-0584b00b24eb4845a3b53f65ba15b6fc/build.binlog");

Console.WriteLine("=== ERRORS ===");
var errors = build.FindChildrenRecursive<Error>();
foreach (var e in errors)
{
    var project = e.GetNearestParent<Project>()?.Name ?? "unknown";
    Console.WriteLine($"[{project}] {e.File}({e.LineNumber},{e.ColumnNumber}): error {e.Code}: {e.Text}");
}

Console.WriteLine("\n=== WARNINGS ===");
var warnings = build.FindChildrenRecursive<Warning>();
foreach (var w in warnings)
{
    var project = w.GetNearestParent<Project>()?.Name ?? "unknown";
    if (w.Code != null && (w.Code.StartsWith("CS") || w.Code.StartsWith("NU") || w.Code.StartsWith("MSB")))
        Console.WriteLine($"[{project}] {w.Code}: {w.Text}");
}

Console.WriteLine("\n=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");

// Check for failed targets/projects
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    if (p.FindChildrenRecursive<Error>().Any())
        Console.WriteLine($"FAILED: {p.Name}");
}
EOF
